"use strict";

// SỬA ĐƯỜNG DẪN: Lùi ra 5 cấp để tìm file utils.js trong thư mục src
// Nếu báo lỗi "Cannot find module", hãy thử đổi thành "../utils"
var utils = require("../../../utils");

module.exports = function (defaultFuncs, api, ctx) {
  return function changeNickname(nickname, threadID, participantID, callback) {
    var resolveFunc = function(){};
    var rejectFunc = function(){};
    var returnPromise = new Promise(function (resolve, reject) {
      resolveFunc = resolve;
      rejectFunc = reject;
    });

    // Xử lý tham số linh hoạt (cho phép bỏ qua callback)
    if (!callback) {
      callback = function (err) {
        if (err) return rejectFunc(err);
        resolveFunc();
      };
    }

    // Nếu không truyền ID người cần đổi, mặc định đổi cho chính mình (hoặc người gọi)
    if (!participantID) participantID = ctx.userID;
    if (!threadID) threadID = ctx.threadID;

    // Kiểm tra kết nối MQTT
    if (!ctx.mqttClient) {
      var err = new Error("Not connected to MQTT");
      callback(err);
      return returnPromise;
    }

    ctx.wsReqNumber += 1;
    ctx.wsTaskNumber += 1;

    // Payload gửi lên Facebook qua MQTT
    const queryPayload = {
      thread_key: threadID.toString(),
      contact_id: participantID.toString(),
      nickname: nickname,
      sync_group: 1,
    };

    const query = {
      failure_count: null,
      label: '44',
      payload: JSON.stringify(queryPayload),
      queue_name: 'thread_participant_nickname',
      task_id: ctx.wsTaskNumber,
    };

    const context = {
      app_id: ctx.appID,
      payload: {
        epoch_id: parseInt(utils.generateOfflineThreadingID()),
        tasks: [query],
        version_id: '24631415369801570',
      },
      request_id: ctx.wsReqNumber,
      type: 3,
    };
    
    // Gửi lệnh
    ctx.mqttClient.publish('/ls_req', JSON.stringify({
        ...context,
        payload: JSON.stringify(context.payload)
    }), { qos: 1, retain: false }, (err) => {
      if (err) return callback(err);
      callback(null);
    });

    return returnPromise;
  };
};